text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي",
  "planted": [
    {
      "slot": "p1",
      "text": "تحتفظ الشركة بحق الاستفادة من كافة البيانات والمعلومات المجمعة من المستخدمين في أي أغراض تشغيلية أو تجارية تراها مناسبة لتطوير أعمالها، دون تقييد بالنطاق الأساسي الذي جُمعت من أجله أو الحاجة إلى إشعار مسبق."
    },
    {
      "slot": "p2",
      "text": "تقتصر تفاصيل نطاق البيانات المجمعة وآليات معالجتها وحفظها على الدوني الإداري الداخلي للشركة، وتتم تلبية طلبات الاستفسار الخاصة بها وفقاً لما تقره الإدارة تقديرياً بعد إتمام عملية التسجيل والحساب."
    },
    {
      "slot": "p3",
      "text": "تُستغل البيانات الصحية والمعلومات البيومترية والحساسة المقدمة عبر المنصة لأغراض التحليل التسويقي المتقدم وتقديم العروض المخصصة، ويُسمح لكافة الأقسام التجارية والتشغيلية بالاطلاع عليها لتسهيل تقديم الخدمات."
    },
    {
      "slot": "p4",
      "text": "في حال وقوع أي اختراق أمني أو وصول غير مصرح به يؤثر على سلامة البيانات، تلتزم الشركة بإخطار الجهة الإشرافية المختصة خلال مدة لا تتجاوز اثنتين وسبعين ساعة من وقت اكتشاف الواقعة، مع إبلاغ المتضررين مباشرة إذا تطلب الأمر."
    },
    {
      "slot": "p5",
      "text": "تُرسل الرسائل الترويجية والإعلانية عبر قنوات الاتصال المتاحة للمستخدمين بناءً على الإعدادات الافتراضية للحساب، مع إتاحة آلية مناسبة للتوقف عن تلقي تلك المواد وفقاً لما تحدده الشركة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية المبرمة عبر المنصة لرسوم الخدمة المقررة والمعلنة مسبقاً، والتي تسدد حصراً عبر وسائل الدفع المعتمدة.",
    "تبدأ المدة الزمنية لهذا الاتفاق اعتباراً من تاريخ تفعيل الحساب وتستمر حتى يتم إنهاؤها من قبل أي من الطرفين وفقاً للآليات المقررة.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناشئة عن استخدام المنصة أو التعذر عن استخدامها.",
    "تُفسر هذه الشروط وتخضع للأنظمة السارية والمعمول بها في المملكة العربية السعودية، وتختص الجهات القضائية بالفصل في أي نزاع ينشأ عنها.",
    "تُعد كافة الحقوق الفكرية والعلامات التجارية والتصميمات الخاصة بالمنصة ملكية خالصة للشركة، ولا يُسمح باستنساخها أو استخدامها دون إذن خطي مسبق.",
    "تعتبر الإشعارات والمراسلات الموجهة بين الطرفين صحيحة وم منتجة لآثارها القانونية إذا تم إرسالها عبر البريد الإلكتروني المسجل أو الوسائل المعتمدة في المنصة."
  ]
}
